# CompositeReviewer：组合模式——将多个审查器合并为统一接口
# 体现「组合优于继承」的设计原则：调用者只需调用一个 review()，
# 内部自动协调多个审查器的工作
# CompositeReviewer：核心类，封装了系统的关键行为和状态
class CompositeReviewer(Reviewer):
    def review(self, diff, parsed):
        # merged 字典用于去重：key=(path, line, rule_id)，后者覆盖前者
        # 初始化字典 merged: Dict[Any, Finding]，用于存储键值对数据
        merged: Dict[Any, Finding] = {}
        errors = []  # 收集各子审查器的异常
        # 依次调用每个子审查器
        for reviewer in self.reviewers:
            try:
                for finding in reviewer.review(diff, parsed):
                    # 以 (路径, 行号, 规则ID) 为键去重
                    key = (finding.path, finding.line, finding.rule_id)
                    merged[key] = finding  # 后者覆盖前者（保留最新结果）
            except Exception as exc:
                # 单个审查器失败不中断——记录异常继续处理下一个
                errors.append(exc)
        # 只有当所有子审查器都失败且没有任何结果时，才抛出异常
        if not merged and errors and len(errors) == len(self.reviewers):
            raise errors[0]  # 全部失败才抛异常
        # 按严重级别排序：CRITICAL > HIGH > MEDIUM > LOW
        # 同级别内按文件路径和行号排序，保证输出稳定可复现
        order = {Severity.CRITICAL: 0, Severity.HIGH: 1, ...}
        return sorted(merged.values(), key=lambda item: (order[item.severity], item.path, item.line))
